from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' not in event:
            winners[('anonymous', position)] = (position, event)
            continue

        key = ('id', event['id'])
        revision = event.get('revision', 0)
        current = winners.get(key)
        if current is None or revision >= current[1]:
            winners[key] = (position, revision, event)

    selected = []
    for key, winner in winners.items():
        if key[0] == 'anonymous':
            position, event = winner
        else:
            position, revision, event = winner
        selected.append((position, event))

    balances = dict(data.get('opening', {}))
    for _, event in sorted(selected, key=lambda item: item[0]):
        if event.get('void') is True:
            continue

        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances[key] = balances.get(key, 0) + amount(event, data['rounding'])

    return {'balances': balances}
